"use client";

/**
 * Perch. A creature on the top edge of whatever you put in it (a Card, a
 * Panel, a Modal's body): sitting there watching, or hiding behind the edge
 * and peeking up when you come near it. It reacts through its mood, like
 * every Creature, and never covers what it sits on: the space it needs
 * above the edge is kept for it.
 *
 * Decorative: the creature is hidden from assistive technology, and what
 * you put in the Perch is read as it is.
 */
import type { CSSProperties, ReactNode } from "react";
import { Creature, type CreatureMood } from "../creature";
import type { CreatureCharacter } from "../creature";
import "./perch.css";

export interface PerchProps {
  /** What it sits on. */
  children: ReactNode;
  /** What it's doing. Default `idle`. */
  mood?: CreatureMood;
  /** Who it is. Default: Echo. */
  character?: CreatureCharacter;
  /** `sit` (default) on the edge; `peek` hides behind it and comes up when you're near. */
  behavior?: "sit" | "peek";
  /** Which end of the edge. Default `end`. */
  at?: "start" | "end";
  /** The creature's height in px. Default 56. */
  size?: number;
}

export function Perch({ children, mood = "idle", character, behavior = "sit", at = "end", size = 56 }: PerchProps) {
  // Its size, as a variable the stylesheet reads: the room kept above the edge.
  const style = { "--perch-size": `${size}px` } as CSSProperties;
  return (
    <div className="echo-perch" data-behavior={behavior} data-at={at} style={style}>
      <div className="echo-perch__ledge" aria-hidden="true">
        <span className="echo-perch__creature">
          <Creature mood={mood} character={character} size={size} />
        </span>
      </div>
      <div className="echo-perch__base">{children}</div>
    </div>
  );
}

/**
 * Perch. The creature stands on the top edge of what's in it: the lower part
 * of its body over the edge, so it sits rather than floats. Peeking, the
 * ledge clips it at the edge and it rises from behind. Composes var(--echo-*).
 */
.echo-perch {
  --perch-size: 56px;
  --perch-over: calc(var(--perch-size) * 0.32);
  position: relative;
  display: grid;
  min-inline-size: 0;
  /* The room it needs above the edge, kept for it. */
  padding-block-start: calc(var(--perch-size) - var(--perch-over));
}
.echo-perch__base {
  position: relative;
  min-inline-size: 0;
}
.echo-perch__ledge {
  position: absolute;
  inset-block-start: 0;
  inset-inline: var(--echo-space-10);
  z-index: var(--echo-z-raised, 1);
  display: flex;
  justify-content: flex-end;
  block-size: var(--perch-size);
  pointer-events: none;
}
.echo-perch[data-at="start"] .echo-perch__ledge {
  justify-content: flex-start;
}
.echo-perch__creature {
  display: inline-flex;
  transition: translate var(--echo-duration-pop) var(--echo-ease-pop);
}

/* Peek: clipped at the edge, down out of sight until you're near. */
.echo-perch[data-behavior="peek"] .echo-perch__ledge {
  block-size: calc(var(--perch-size) - var(--perch-over));
  overflow: hidden;
  --echo-clip: decorative;
}
.echo-perch[data-behavior="peek"] .echo-perch__creature {
  translate: 0 70%;
}
.echo-perch[data-behavior="peek"]:focus-within .echo-perch__creature {
  translate: 0 12%;
}
@media (hover: hover) {
  .echo-perch[data-behavior="peek"]:hover .echo-perch__creature {
    translate: 0 12%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .echo-perch__creature {
    transition: none;
  }
}
